$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'De automatische configuratie maakt de webhook alleen aan voor de URL van deze site, of voegt de ontbrekende gebeurtenissen eraan toe en behoudt alle andere gebeurtenissen. De webhook-ID die wordt gebruikt om handtekeningen te verifiëren, wordt opgeslagen. Er worden nooit webhooks verwijderd, nooit andere URL\'s gewijzigd en nooit de app-machtigingen aangepast.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'De automatische configuratie vereist Webhook Endpoints: Write. Hiermee wordt de webhook aangemaakt en het nieuwe ondertekeningsgeheim veilig opgeslagen, of wordt het bestaande endpoint ingeschakeld en worden ontbrekende gebeurtenissen toegevoegd. Bestaande gebeurtenissen blijven behouden en endpoints of API-sleutelmachtigingen worden niet vervangen of gewijzigd.';
$t['Automatic sign-in is unavailable. You can sign in inside Local Encoder with your username and password.'] = 'Automatisch inloggen is niet beschikbaar. Je kunt in Local Encoder inloggen met je gebruikersnaam en wachtwoord.';
