$t['Final test: complete a sandbox purchase, confirm an HTTP 200 delivery in Stripe, then check the wallet or rental, subscription access and video playback. Also test a declined card and 3D Secure. Never retry a charged payment just because access is still pending.'] = 'Laatste test: voltooi een sandboxaankoop, controleer een HTTP 200-aflevering in Stripe en controleer daarna de wallet of huur, abonnementstoegang en het afspelen van video\'s. Test ook een geweigerde kaart en 3D Secure. Probeer een afgeschreven betaling nooit opnieuw alleen omdat de toegang nog in behandeling is.';
$t['Final test: complete a sandbox purchase with a Personal sandbox buyer, confirm an HTTP 200 webhook delivery in developer.paypal.com, then check the wallet, rental, subscription and video playback. Never retry a paid purchase just because access is still pending.'] = 'Laatste test: voltooi een sandboxaankoop met een persoonlijke sandboxkoper, controleer een HTTP 200-webhookaflevering op developer.paypal.com en controleer daarna de wallet, huur, het abonnement en het afspelen van video\'s. Probeer een betaalde aankoop nooit opnieuw alleen omdat de toegang nog in behandeling is.';
