$t['The comment is empty'] = 'The comment is empty';
$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'De commit geeft de Git-revisie aan die op deze server is uitgecheckt; lokale bestandswijzigingen zijn niet inbegrepen. Er wordt een Git-tag getoond als die direct naar die commit verwijst.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'De Companion Chat-dienst is momenteel niet beschikbaar. Vraag je sitebeheerder de verbinding van de AI-plug-in te controleren.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'De verbinding kon niet worden vernieuwd. Koppel je account opnieuw.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'De verbinding is verlopen en kon niet worden vernieuwd. Koppel je account opnieuw.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'De verbinding met de bestemming is tijdens het streamen verbroken. Dit kan een tijdelijk netwerkprobleem zijn; FFMPEG probeert opnieuw verbinding te maken.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'De verbinding met YouTube is onderbroken. De upload is gepauzeerd en kan worden hervat.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'De verbinding is onderbroken. Controleer je account voordat je dit abonnement opnieuw probeert.';
$t['The connection was renewed.'] = 'De verbinding is vernieuwd.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Het verbindingsvenster is gesloten voordat de autorisatie was voltooid. Er is geen account gekoppeld.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'De geconverteerde bestanden zijn bewaard. Neem contact op met de sitebeheerder om de overdracht opnieuw te proberen; je hoeft de video niet opnieuw te uploaden.';
$t['The converted video could not be sent back to this site.'] = 'De geconverteerde video kon niet worden teruggestuurd naar deze site.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'De klanten van de geselecteerde kaart. Zoek, sorteer, kopieer de e-mailadressen of exporteer alles naar een spreadsheet.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Het dagelijkse YouTube-uploadquotum van deze website is bereikt. Uploads zijn weer beschikbaar na middernacht Pacific Time. Probeer het later opnieuw.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'De databaseversie verandert alleen wanneer er een databasemigratie wordt toegepast. Deze hoeft niet overeen te komen met de releasetag of commit.';
$t['The default'] = 'De standaard';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'De RTMP-doelserver heeft de verbinding geweigerd. Controleer de stream-URL en zorg ervoor dat de server online is.';
$t['The destination server requires authentication. Check the stream key.'] = 'De doelserver vereist authenticatie. Controleer de streamsleutel.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'De doelserver gaf 403 terug. De streamsleutel is mogelijk ongeldig of verlopen.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'De doelvideo is verwijderd of dit account kan hem niet bewerken. Controleer de video en de accounttoegang op de site.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'De downloadtoestemming geldt voor de hele site, dus er valt niets te controleren bij de video';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'The download permission is site wide, so there is nothing to check onthe video';
$t['The email is invalid'] = 'The email is invalid';
$t['The encoder could not download the original file.'] = 'De encoder kon het originele bestand niet downloaden.';
$t['The encoder could not find this video on the site.'] = 'De encoder kon deze video niet vinden op de site.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'De encoder heeft niet bevestigd dat de video aan de wachtrij is toegevoegd. Probeer het opnieuw.';
$t['The encoder is running out of disk space'] = 'De encoder heeft bijna geen schijfruimte meer';
$t['The encoder reported an unexpected error.'] = 'De encoder heeft een onverwachte fout gemeld.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Het coderingsproces is onverwacht gestopt en de automatische nieuwe pogingen zijn ook mislukt.';
$t['The encoding queue is stalled'] = 'De coderingswachtrij staat stil';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'De aankoop van het evenement kon niet worden voltooid. Je walletbetaling is niet afgeschreven. Controleer je saldo voordat je het opnieuw probeert.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Het bestand kon niet worden geconverteerd. Het is mogelijk beschadigd of gebruikt een formaat dat de encoder niet ondersteunt.';
$t['The file must be an .vtt file!'] = 'The file must be an .vtt file!';
$t['The file must be an .vtt or .srt file!'] = 'Het bestand moet een .vtt- of .srt-bestand zijn!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'De uiteindelijke kosten zijn gebaseerd op de duur die tijdens de verwerking is gemeten. Een gekoppelde Marketplace-wallet is vereist.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'De volgende film bevat materiaal dat niet geschikt is voor kinderen van 17 jaar en jonger.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'De volgende film bevat materiaal dat mogelijk niet geschikt is voor kinderen van 17 jaar en jonger.';
$t['The form to signup will not exists'] = 'The form to signup will not exists';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'De cadeaucode is geannuleerd. Als dit onverwacht is, neem dan contact op met ons supportteam.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'De cadeaucode is momenteel inactief. Kom later terug of neem contact op met support.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'De bovenstaande informatie komt overeen met onze officiële gegevens en bevestigt de echtheid van dit certificaat.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'De invoerstream bevat ongeldige gegevens. De HLS-bron is mogelijk nog niet klaar of de stream is onderbroken.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Het geïnstalleerde PHP-pakket bevat beide fixes, maar dit webproces gebruikt nog de kopie die vóór de update is geladen. Herstart Apache of PHP-FPM.';
$t['Their last plans add up to %s'] = 'Hun laatste abonnementen komen samen op %s';
$t['The list was limited to the first %s results.'] = 'De lijst is beperkt tot de eerste %s resultaten.';
$t['The live service could not complete the request. Please try again.'] = 'De livedienst kon het verzoek niet voltooien. Probeer het opnieuw.';
$t['The live that was still being sent to this destination was stopped.'] = 'De livestream die nog naar deze bestemming werd verzonden, is gestopt.';
$t['Theme for Style:'] = 'Theme for Style:';
$t['Themes'] = 'Thema\'s';
$t['The number of lines in both columns must be the same'] = 'Het aantal regels in beide kolommen moet gelijk zijn';
$t['The original file for this video does not exists anymore'] = 'Het origineel videobestand bestaat niet meer';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'The Permissions Plugin is not installed. Please install it if you want to customize the permissions.';
$t['The plugin is disabled'] = 'The plugin is disabled';
$t['The program is empty'] = 'The program is empty';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'De aankoop kon niet worden voltooid. Je walletbetaling is niet afgeschreven. Controleer je saldo voordat je het opnieuw probeert.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'Er is een onbekende status gekoppeld aan deze cadeaucode. Neem contact op met support voor hulp.';
$t['There, you can set'] = 'There, you can set';
$t['There are no notifications'] = 'Er zijn geen meldingen';
$t['There are no upcoming events for this channel'] = 'Er zijn geen aankomende evenementen voor dit kanaal';
$t['There are various kinds of media you can integrate here. They are working different'] = 'There are various kinds of media you can integrate here. They are working different';
$t['The recover pass does not match!'] = 'Het herstelwachtwoord is niet correct!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'The regular form to signin will not exist, if you check this will only have social login or LDAP option';
$t['There is missing data to recover your password'] = 'Niet alle informatie om het wachtwoord te herstellen is beschikbaar';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Er is nog geen Pay Per View-abonnement. Maak er een aan in de Pay-Per-View-plugin, tabblad PPV Plans.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Er is nog geen abonnement dat video\'s kan bevatten. Maak er een aan in het tabblad PPV Plans en kom dan hier terug.';
$t['There is no streaming now'] = 'There is no streaming now';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Het releasenummer en de AVideo-databaseversie staan los van elkaar. De updatestatus van de code wordt bepaald door de commitgeschiedenis.';
$t['The request to the social network failed. Please try again later.'] = 'Het verzoek aan het sociale netwerk is mislukt. Probeer het later opnieuw.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'De restreamerserver kan de bestemming niet bereiken. Controleer de netwerkverbinding.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Dezelfde melding wordt hoogstens elke %s herhaald zolang het probleem aanhoudt.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Dezelfde melding wordt hoogstens om de paar uur herhaald zolang het probleem aanhoudt.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'De geselecteerde camera of microfoon is niet beschikbaar. Kies een ander apparaat.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'De geselecteerde positie wordt gemarkeerd op een echte pagina. De mobiele voorvertoning wijzigt alleen de advertentieposities; de rest van de pagina gebruikt het apparaat van je browser.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'De geselecteerde positie wordt omlijnd op een echte pagina van je site en volgt de positie die je hieronder kiest. Het mobiele voorbeeld wijzigt alleen de advertentieposities; de rest van de pagina gebruikt het apparaat van je browser.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'De site is momenteel offline vanwege een databaseprobleem. We werken eraan om het probleem zo snel mogelijk op te lossen.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'De site is tijdelijk niet beschikbaar omdat de schijf van de server vol is. We werken aan dit probleem en zijn snel weer terug.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'De site is in onderhoud omdat de schijf van de server bijna vol is. We pakken het probleem aan en zijn snel weer terug.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'De site heeft de toegang geweigerd. Vernieuw de toegang van het encoderaccount en controleer de uploadrechten.';
$t['The site will display only a login form to un authenticated users'] = 'The site will display only a login form to un authenticated users';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'De bronstream is beëindigd. Als de livestream bewust is gestopt, is dit normaal.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'De splitsing staat aan: desktopbezoekers zien deze banner nu niet, ze zien de linker- en rechterhelft.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'De stream bevat onderbrekingen in de tijdstempels. Dit kan buffering of afspeelproblemen veroorzaken op het doelplatform.';
$t['The subtitle has not been copied to the player yet.'] = 'De ondertitel is nog niet naar de speler gekopieerd.';
$t['The subtitle is already on the player.'] = 'De ondertitel staat al in de speler.';
$t['The subtitle was copied to the player.'] = 'De ondertitel is naar de speler gekopieerd.';
$t['The subtitle will be available when processing finishes.'] = 'De ondertitel is beschikbaar zodra de verwerking is voltooid.';
$t['The upload could not be started. Please try again.'] = 'De upload kon niet worden gestart. Probeer het opnieuw.';
$t['The upload did not start. Click Resume to try again.'] = 'De upload is niet gestart. Klik op Hervatten om het opnieuw te proberen.';
$t['The upload to YouTube started. You can follow its progress below, it continues even if you close this window.'] = 'De upload naar YouTube is gestart. Je kunt de voortgang hieronder volgen; deze gaat door, ook als je dit venster sluit.';
$t['The upload was canceled.'] = 'De upload is geannuleerd.';
$t['The upload was interrupted. Click Resume to continue from where it stopped.'] = 'De upload is onderbroken. Klik op Hervatten om verder te gaan waar hij gestopt is.';
$t['The upload was resumed.'] = 'De upload is hervat.';
$t['the user is inactive'] = 'the user is inactive';
$t['The username must be an email'] = 'The username must be an email';
$t['The user will be able to edit their name and CPF.'] = 'De gebruiker kan zijn naam en CPF bewerken.';
$t['The video could not be published. Please try again later.'] = 'De video kon niet worden gepubliceerd. Probeer het later opnieuw.';
$t['The video file could not be found on this server, so it cannot be sent to YouTube.'] = 'Het videobestand kon niet worden gevonden op deze server, dus het kan niet naar YouTube worden verzonden.';
$t['The video is empty'] = 'The video is empty';
$t['The video was published.'] = 'De video is gepubliceerd.';
$t['The website pages do not display this position, so there is nothing to preview.'] = 'De websitepagina\'s tonen deze positie niet, dus er is niets om te bekijken.';
$t['The website pages do not display this position at the moment. Images saved here are only returned by the API.'] = 'De websitepagina\'s tonen deze positie momenteel niet. Afbeeldingen die hier worden opgeslagen, worden alleen door de API teruggegeven.';
$t['They are likely to leave at renewal time. Invite them back with a suggested course or a live class.'] = 'Ze zullen waarschijnlijk vertrekken bij de verlenging. Nodig ze opnieuw uit met een voorgestelde cursus of een liveles.';
$t['They have paid %s in total'] = 'Ze hebben in totaal %s betaald';
$t['The YouTube authorization could not be renewed because the authorization service did not answer. Please try again in a few minutes.'] = 'De YouTube-autorisatie kon niet worden vernieuwd omdat de autorisatiedienst niet reageerde. Probeer het over een paar minuten opnieuw.';
$t['The YouTube categories could not be loaded, YouTube will choose one.'] = 'De YouTube-categorieën konden niet worden geladen, YouTube kiest er zelf een.';
$t['The YouTube integration is not configured correctly. Please contact the site administrator.'] = 'De YouTube-integratie is niet correct geconfigureerd. Neem contact op met de sitebeheerder.';
$t['The {videoName} video was reported as inappropriate'] = 'The {videoName} video was reported as inappropriate';
$t['Third Party Ads'] = 'Advertenties van derden';
$t['This account has been disabled. Contact support for details.'] = 'Dit account is uitgeschakeld. Neem contact op met support voor meer informatie.';
$t['This account is disabled because the connected marketplace wallet balance ran out. Add credits to your marketplace wallet to reactivate automatically - content is at risk of deletion after 24 hours.'] = 'Dit account is uitgeschakeld omdat het saldo van de gekoppelde marketplace-wallet op is. Voeg tegoed toe aan je marketplace-wallet om automatisch te heractiveren - content loopt het risico na 24 uur te worden verwijderd.';
$t['This action can not be recovered!'] = 'Deze actie kan niet worden hersteld!';
$t['This action cannot be undone. The user will need to confirm their identity again.'] = 'Deze actie kan niet ongedaan worden gemaakt. De gebruiker moet zijn identiteit opnieuw bevestigen.';
$t['This ad goes on the LEFT half of the banner.'] = 'Deze advertentie komt op de LINKER helft van de banner.';
$t['This ad goes on the RIGHT half of the banner.'] = 'Deze advertentie komt op de RECHTER helft van de banner.';
$t['This administration page is unavailable. Update AVideo and try again.'] = 'Deze beheerpagina is niet beschikbaar. Werk AVideo bij en probeer het opnieuw.';
$t['This ad position is not displayed on this page.'] = 'Deze advertentiepositie wordt niet op deze pagina weergegeven.';
$t['This also reset the Chat and views counter'] = 'Dit reset ook de chat en de weergaveteller';
$t['This Bitcoin invoice was marked invalid. If you sent a payment, contact support with the reference on this page.'] = 'Deze Bitcoin-factuur is als ongeldig gemarkeerd. Als je een betaling hebt verzonden, neem dan contact op met support met de referentie op deze pagina.';
$t['This button is always a click worth'] = 'This button is always a click worth';
$t['This category allow download'] = 'This category allow download';
$t['This category does not belong to you'] = 'Deze categorie is niet van jou';
$t['This category do not allow download'] = 'This category do not allow download';
$t['This certificate has been verified and is authentic'] = 'Dit certificaat is geverifieerd en is echt';
$t['This certificate was issued through our secure system and can be verified at any time through this URL.'] = 'Dit certificaat is uitgegeven via ons beveiligde systeem en kan op elk moment via deze URL worden geverifieerd.';
$t['This comment was reported to our team, we will review it soon'] = 'Deze reactie is gemeld bij ons team, we zullen deze binnenkort beoordelen';
$t['This connection expired. Connect the account again to keep publishing.'] = 'Deze verbinding is verlopen. Koppel het account opnieuw om te blijven publiceren.';
$t['This content is for viewers 18+'] = 'Deze content is voor kijkers van 18+';
$t['This content is restricted to viewers 18 and over'] = 'Deze content is alleen toegankelijk voor kijkers van 18 jaar en ouder';
$t['This could be due to the enabled filters'] = 'Dit kan komen door de ingeschakelde filters';
$t['This creates a download-button under your video, suggest you title.mp4 as download-name.'] = 'This creates a download-button under your video, suggest you title.mp4 as download-name.';
$t['This destination is still sending a live and it could not be stopped, so it was not deleted. Stop it in Active Lives and try again.'] = 'Deze bestemming verzendt nog een livestream die niet kon worden gestopt, dus is deze niet verwijderd. Stop hem in Actieve livestreams en probeer het opnieuw.';
$t['This e-mail will be used for this web site notifications'] = 'Dit mailadres zal worden gebruikt als afzender ';
$t['This event is not available for purchase.'] = 'Dit evenement is niet beschikbaar voor aankoop.';
$t['This export includes only data stored in wallet and wallet_log tables, plus user and email from users table.'] = 'Deze export bevat alleen gegevens uit de tabellen wallet en wallet_log, plus gebruiker en e-mail uit de tabel users.';
$t['This file has lines that could not be read; fix it by hand'] = 'Dit bestand bevat regels die niet konden worden gelezen; corrigeer ze handmatig';
